import { Poi, TransitStation } from '../types';

// Generated by `npm run data:osm` (see scripts/fetch-osm.mjs) from OpenStreetMap contributors, ODbL 1.0.
// import.meta.glob keeps the build working even before the first data file exists.
interface OsmFile<T> {
  meta: { source: string; fetchedAt: string; count: number; relationName?: string };
  items: T[];
}
const files = import.meta.glob('./osm/*.json', { eager: true, import: 'default' }) as Record<string, OsmFile<any>>;
const load = <T>(name: string): OsmFile<T> | null => files[`./osm/${name}.json`] ?? null;

const orange = load<TransitStation>('orangeline');
const metro = load<TransitStation>('metrobus');
const hospitals = load<Poi>('hospitals');
const fuel = load<Poi>('fuel');

export const ORANGELINE_STATIONS: TransitStation[] = orange?.items ?? [];
export const METROBUS_STATIONS: TransitStation[] = metro?.items ?? [];
export const HOSPITALS: Poi[] = hospitals?.items ?? [];
export const FUEL_STATIONS: Poi[] = fuel?.items ?? [];
export const ALL_POIS: Poi[] = [...HOSPITALS, ...FUEL_STATIONS];

/** Latest extraction date across the files, for "data from OpenStreetMap, updated …" credits. */
export const OSM_UPDATED: string | null =
  [orange, metro, hospitals, fuel].map((f) => f?.meta.fetchedAt).filter(Boolean).sort().at(-1)?.slice(0, 10) ?? null;

export const OSM_CREDIT = '© OpenStreetMap contributors (ODbL)';

export const stationName = (s: { name: string; nameUrdu: string | null }, rtl: boolean) => (rtl && s.nameUrdu) || s.name;
